#!/bin/bash
# Rebuilds statements.html from the generated partials.
#
# The body is generated by the module generator from the twenty-section
# specification, so every numbered sub-item is present by construction and
# the figures stay consistent across sections.
set -e
cd "$(dirname "$0")"

python3 _gen_statements.py
cat _statements.css _statements2.css > _statements-build.css
python3 _compose.py _smhead.html statements _statements-build.css

{
  cat _smhead.html
  cat _sm2body.html
  cat _sm2js.js
  printf '</body>\n</html>\n'
} > statements.html

python3 - <<'PYEOF'
import pathlib
p = pathlib.Path('statements.html')
s = p.read_text()
s = s.replace('<title>Module — GOLDEN FINANCIAL SERVICES</title>',
              '<title>Statements — GOLDEN FINANCIAL SERVICES</title>')
p.write_text(s)
print('built statements.html', len(s), 'bytes')
PYEOF

python3 inject_backnav.py statements.html
